demo_admission:
  runs-on: ubuntu-latest
  timeout-minutes: 19
  env:
    PREVIEW_HEAD_SHA: ${{ github.event.pull_request.head.sha }}
    PREVIEW_RUN_URL: ${{ github.server_url }}/${{ github.repository }}/actions/runs/${{ github.run_id }}
  outputs:
    proof: ${{ steps.admission_receipt.outputs.proof }}
    artifactId: ${{ steps.admission_artifact.outputs.artifact-id }}
    artifactURL: ${{ steps.admission_artifact.outputs.artifact-url }}
    artifactDigest: ${{ steps.admission_artifact.outputs.artifact-digest }}
  steps:
    - uses: actions/checkout@fbc6f3992d24b796d5a048ff273f7fcc4a7b6c09 # v5
      timeout-minutes: 3
      with:
        ref: ${{ github.event.pull_request.head.sha }}
        persist-credentials: false
    - uses: actions/setup-node@a0853c24544627f65ddf259abe73b1d18a591444 # v5
      timeout-minutes: 2
      with:
        node-version: '22.13.1'

concurrency:
  group: company-candidate-${{ github.event.pull_request.number || github.ref }}
  cancel-in-progress: true

concurrency:
  group: industrial-features-${{ github.event.pull_request.number }}
  cancel-in-progress: true
